function make(){
 const groups=Array.from({length:18},(_,n)=>({id:`topic-${String(n+1).padStart(2,'0')}`,parentId:'fixture-parent',label:`Testovací okruh ${n+1}`}));
 const items=words.map(([fr,cz],n)=>({id:n+1,uid:`vfr-${String(n+1).padStart(4,'0')}`,fr,cz,sentenceFr:`Voici « ${fr} ».`,sentenceCz:`Testovací věta ${n+1}.`,genderFr:n<6?'m':'',active:true,image:`assets/vocabulary-fr-v2/images/fixture-${n+1}.webp`,thumbnail:`assets/vocabulary-fr-v2/thumbs/fixture-${n+1}.webp`,imageReviewed:true,imageRole:'meaning',primaryGroup:groups[n].id,topicIds:[groups[n].id],partOfSpeech:[n<6?'noun':'other'],teachingType:n===14?'interaction':'word',expressionType:'word',difficultyBand:1,difficultyStatus:'editorial',addedAt:'2026-01-01',legacyAddedAt:null,origin:'synthetic-fixture',lemma:fr,formOfUid:null,related:[]}));
 items[0].sentenceFr='Un chat regarde la lune.';
 const data={schemaVersion:2,appName:'VocabularyFR',language:'fr',translationLanguage:'cs',mode:'fixture',imageReviewComplete:true,audioStatus:'complete',itemCount:items.length,sourceRowCount:items.length,parents:[{id:'fixture-parent',label:'Testovací témata'}],groups,items,stats:{pendingImageReview:0},provenance:{catalogSha256:'synthetic-client-fixture-v1'}};
 function audio(kind){return {schemaVersion:1,language:'fr',kind,status:'complete',rate:'-10%',voices:{fr:'synthetic-fixture',cz:'synthetic-fixture'},items:Object.fromEntries(items.map(i=>[i.uid,{uid:i.uid,sourceFr:i.fr,sourceCz:i.cz,...(kind==='sentences'?{sourceSentenceFr:i.sentenceFr,sourceSentenceCz:i.sentenceCz}:{}),spokenFr:kind==='sentences'?i.sentenceFr:i.fr,spokenCz:kind==='sentences'?i.sentenceCz:i.cz,fr:`assets/vocabulary-fr-${kind==='sentences'?'sentences':'audio'}/fixture/${i.uid}-fr.mp3`,cz:`assets/vocabulary-fr-${kind==='sentences'?'sentences':'audio'}/fixture/${i.uid}-cz.mp3`}]))};}
 const quiz={schemaVersion:1,language:'fr',kind:'spelling-pictures',entries:Object.fromEntries(items.map(i=>[i.uid,{uid:i.uid,fr:i.fr,cz:i.cz,image:i.image,thumbnail:i.thumbnail,pieces:[i.fr],reviewed:false,displayMode:'whole-word',format:'objects',conflicts:[]}]))};
 const pictures={schemaVersion:1,language:'fr',kind:'sentence-pictures',maxPictures:5,entries:Object.fromEntries(items.map(i=>{const refs=i.id===1?[i,items[2]]:[i];return [i.uid,{sourceFr:i.fr,sourceCz:i.cz,sourceSentenceFr:i.sentenceFr,sourceSentenceCz:i.sentenceCz,reviewed:true,concepts:refs.map(r=>({uid:r.uid,sourceFr:r.fr,sourceCz:r.cz,text:r.fr,occurrence:1,start:i.sentenceFr.indexOf(r.fr),end:i.sentenceFr.indexOf(r.fr)+r.fr.length}))}];}))};
 return {data,audio:audio('words'),sentenceAudio:audio('sentences'),quiz,pictures};
}
